64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
73	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
74	     * stored lower-cased.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** Dedicated audit logger; one line is emitted per successful owner create. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    /**
83	     * The maximum number of owners a single city may contain. Once a city already holds this many
84	     * owners, any further create naming that city is rejected as a conflict.
85	     */
86	    private static final int MAX_OWNERS_PER_CITY = 50;
87	
88	    /**
89	     * The maximum number of owners that may be registered in a single day. Once this many owners
90	     * already carry today's registration date, any further create is rejected as too many requests.
91	     */
92	    private static final int MAX_OWNERS_PER_DAY = 100;
93	
94	    /**
95	     * The number of owners that must already be registered on today's business day before a response
96	     * carries a bulk-signup warning. Once more than this many owners already carry today's
97	     * registration date, responses set {@code bulkSignupWarning} true.
98	     */
99	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
100	
101	    private final ClinicService clinicService;
102	
103	    private final OwnerMapper ownerMapper;
104	
105	    private final PetMapper petMapper;
106	
107	    private final VisitMapper visitMapper;
108	
109	    public OwnerRestControllerV1(ClinicService clinicService,
110	                                 OwnerMapper ownerMapper,
111	                                 PetMapper petMapper,
112	                                 VisitMapper visitMapper) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        OwnerDto ownerDto = toOwnerDto(owner);
143	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
144	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        validateRequiredOwnerFields(ownerFieldsDto);
151	        LocalDate suppliedOrDefaultDate =
152	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
153	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
154	        rejectDailyLimitExceeded(registrationDate);
155	        rejectCityAtCapacity(ownerFieldsDto.getCity());
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        owner.setAddress(normalizeAddress(owner.getAddress()));
159	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
160	        owner.setTelephone(normalizedTelephone);
161	        rejectDuplicateTelephone(normalizedTelephone);
162	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
163	        owner.setEmail(normalizeEmail(owner.getEmail()));
164	        owner.setRegistrationDate(registrationDate);
165	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
166	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
167	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
168	        this.clinicService.saveOwner(owner);
169	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
171	        OwnerDto ownerDto = toOwnerDto(owner);
172	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
190	        this.clinicService.saveOwner(currentOwner);
191	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Transactional
196	    @Override
197	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        this.clinicService.deleteOwner(owner);
203	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        HttpHeaders headers = new HttpHeaders();
214	        Pet pet = petMapper.toPet(petFieldsDto);
215	        owner.setId(ownerId);
216	        pet.setOwner(owner);
217	        pet.getType().setName(null);
218	        this.clinicService.savePet(pet);
219	        PetDto petDto = petMapper.toPetDto(pet);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
221	            .buildAndExpand(pet.getId()).toUri());
222	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner != null) {
230	            Pet currentPet = this.clinicService.findPetById(petId);
231	            if (currentPet != null) {
232	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
233	                currentPet.setName(petFieldsDto.getName());
234	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
235	                this.clinicService.savePet(currentPet);
236	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
245	        HttpHeaders headers = new HttpHeaders();
246	        Visit visit = visitMapper.toVisit(visitFieldsDto);
247	        Pet pet = new Pet();
248	        pet.setId(petId);
249	        visit.setPet(pet);
250	        this.clinicService.saveVisit(visit);
251	        VisitDto visitDto = visitMapper.toVisitDto(visit);
252	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
253	            .buildAndExpand(visit.getId()).toUri());
254	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
255	    }
256	
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner != null) {
263	            Pet pet = owner.getPet(petId);
264	            if (pet != null) {
265	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
266	            }
267	        }
268	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	    }
270	
271	    /**
272	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
273	     * offending field is collected so the caller learns exactly which values must be supplied.
274	     *
275	     * @param ownerFieldsDto the submitted owner payload
276	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
277	     *         telephone is missing or blank
278	     */
279	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
280	        List<String> missingFields = new ArrayList<>();
281	        if (isBlank(ownerFieldsDto.getFirstName())) {
282	            missingFields.add("firstName");
283	        }
284	        if (isBlank(ownerFieldsDto.getLastName())) {
285	            missingFields.add("lastName");
286	        }
287	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
288	            missingFields.add("address");
289	        }
290	        if (isBlank(ownerFieldsDto.getCity())) {
291	            missingFields.add("city");
292	        }
293	        if (isBlank(ownerFieldsDto.getTelephone())) {
294	            missingFields.add("telephone");
295	        }
296	        if (!missingFields.isEmpty()) {
297	            throw new MissingOwnerFieldsException(missingFields);
298	        }
299	    }
300	
301	    private boolean isBlank(String value) {
302	        return value == null || value.isBlank();
303	    }
304	
305	    /**
306	     * Counts the existing owners who, before this create, already share the given first and last name.
307	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
308	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
309	     * case or spacing still count as the same name.
310	     *
311	     * @param firstName the first name of the owner being created
312	     * @param lastName the last name of the owner being created
313	     * @return the number of existing owners sharing both names (zero when none)
314	     */
315	    private int countNamesakes(String firstName, String lastName) {
316	        String first = normalizeHouseholdField(firstName);
317	        String last = normalizeHouseholdField(lastName);
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
320	                && normalizeHouseholdField(existing.getLastName()).equals(last))
321	            .count();
322	    }
323	
324	    /**
325	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
326	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
327	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
328	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
329	     * more owners the create is rejected as a conflict.
330	     *
331	     * @param city the city of the owner being created
332	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
333	     */
334	    /**
335	     * Rejects an owner create once the maximum number of owners have already been registered on the
336	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
337	     * which is always a business day (a weekend effective date is rolled forward to the following
338	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
339	     * business day the create is rejected as too many requests. Because a weekend effective date is
340	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
341	     *
342	     * @param businessDay the adjusted business day the owner being created would be registered on
343	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
344	     */
345	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
346	        long ownersOnDay = this.clinicService.findAllOwners().stream()
347	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
348	            .count();
349	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
350	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
351	        }
352	    }
353	
354	    /**
355	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
356	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
357	     * was supplied on the request or defaulted to the server's current date.
358	     *
359	     * @param date the effective registration date (supplied or defaulted)
360	     * @return the same date when it is a weekday, otherwise the following Monday
361	     */
362	    /**
363	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
364	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
365	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
366	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
367	     *
368	     * @return {@code true} when more than the threshold number of owners are already registered on
369	     *         today's business day, otherwise {@code false}
370	     */
371	    private boolean isBulkSignupWarningActive() {
372	        LocalDate today = toBusinessDay(LocalDate.now());
373	        long ownersToday = this.clinicService.findAllOwners().stream()
374	            .filter(existing -> today.equals(existing.getRegistrationDate()))
375	            .count();
376	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
377	    }
378	
379	    private LocalDate toBusinessDay(LocalDate date) {
380	        return switch (date.getDayOfWeek()) {
381	            case SATURDAY -> date.plusDays(2);
382	            case SUNDAY -> date.plusDays(1);
383	            default -> date;
384	        };
385	    }
386	
387	    private void rejectCityAtCapacity(String city) {
388	        String normalizedCity = normalizeHouseholdField(city);
389	        long ownersInCity = this.clinicService.findAllOwners().stream()
390	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
391	            .count();
392	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
393	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
394	        }
395	    }
396	
397	    /**
398	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
399	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
400	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
401	     * of owners already in that city (e.g. 'SYD-SMI-0007').
402	     *
403	     * @param city the owner's city
404	     * @param lastName the owner's last name
405	     * @return the formatted customer code
406	     */
407	    private String generateCustomerCode(String city, String lastName) {
408	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
409	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
410	        String normalizedCity = normalizeHouseholdField(city);
411	        int sequence = (int) this.clinicService.findAllOwners().stream()
412	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
413	            .count() + 1;
414	        return String.format("%s-%s-%04d", city3, last3, sequence);
415	    }
416	
417	    /**
418	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
419	     * customerCode is the owner's customer code and YY is the last two digits of the
420	     * registrationDate year (e.g. 'SMI-0007-M26').
421	     *
422	     * @param customerCode the owner's customer code
423	     * @param registrationDate the owner's registration date
424	     * @return the formatted membership number
425	     */
426	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
427	        String yy = String.format("%02d", registrationDate.getYear() % 100);
428	        return customerCode + "-M" + yy;
429	    }
430	
431	    /**
432	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
433	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
434	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
435	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
436	     * stored and returned.
437	     *
438	     * @param telephone the raw telephone value from the request
439	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
440	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
441	     */
442	    private String normalizeTelephone(String telephone) {
443	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
444	        String e164;
445	        if (cleaned.startsWith("+")) {
446	            e164 = cleaned;
447	        } else {
448	            String national = cleaned;
449	            if (national.startsWith("0")) {
450	                national = national.substring(1);
451	            }
452	            e164 = "+61" + national;
453	        }
454	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
455	            throw new InvalidOwnerFieldsException(List.of("telephone"));
456	        }
457	        return e164;
458	    }
459	
460	    /**
461	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
462	     * left unset. When a value is present it must be a syntactically valid address; the normalized
463	     * form stored and returned is the value lower-cased.
464	     *
465	     * @param email the raw email value from the request, or {@code null} when none was supplied
466	     * @return the lower-cased email, or {@code null} when no email was supplied
467	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
468	     */
469	    private String normalizeEmail(String email) {
470	        if (email == null || email.isBlank()) {
471	            return null;
472	        }
473	        if (!EMAIL_PATTERN.matcher(email).matches()) {
474	            throw new InvalidOwnerFieldsException(List.of("email"));
475	        }
476	        return email.toLowerCase(Locale.ROOT);
477	    }
478	
479	    /**
480	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
481	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
482	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
483	     * normalized form is what gets stored, returned and used for every address comparison (the
484	     * required-field check, household duplicate detection and the shared household id).
485	     *
486	     * @param address the raw address value from the request, or {@code null}
487	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
488	     */
489	    private String normalizeAddress(String address) {
490	        if (address == null) {
491	            return "";
492	        }
493	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
494	        if (collapsed.isEmpty()) {
495	            return "";
496	        }
497	        String[] tokens = collapsed.split(" ");
498	        for (int i = 0; i < tokens.length; i++) {
499	            switch (tokens[i]) {
500	                case "ST" -> tokens[i] = "STREET";
501	                case "RD" -> tokens[i] = "ROAD";
502	                case "AVE" -> tokens[i] = "AVENUE";
503	                default -> { }
504	            }
505	        }
506	        return String.join(" ", tokens);
507	    }
508	
509	    /**
510	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
511	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
512	     * directly and is therefore independent of the punctuation a caller supplied.
513	     *
514	     * @param e164Telephone the E.164 telephone of the owner being created
515	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
516	     */
517	    private void rejectDuplicateTelephone(String e164Telephone) {
518	        boolean inUse = this.clinicService.findAllOwners().stream()
519	            .map(Owner::getTelephone)
520	            .filter(existing -> existing != null)
521	            .anyMatch(e164Telephone::equals);
522	        if (inUse) {
523	            throw new DuplicateOwnerTelephoneException(e164Telephone);
524	        }
525	    }
526	
527	    /**
528	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
529	     * last name and a normalized address: last names are compared case-insensitively after whitespace
530	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
531	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
532	     * abbreviation still count as the same household.
533	     * <p>
534	     * When the owner's last name and address already belong to at least one other owner the behaviour
535	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
536	     * household. If it is true the create is allowed and every member of the household - the existing
537	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
538	     * read. When no other owner shares the last name and address no identifier is assigned.
539	     *
540	     * @param owner the owner being created
541	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
542	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
543	     *         address and {@code sharesHousehold} is not true
544	     */
545	    /**
546	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
547	     * household member count} so the derived membership tier is computed correctly (an owner whose
548	     * household holds three or more members is 'GOLD'; otherwise the SILVER/BRONZE rules apply).
549	     *
550	     * @param owner the owner to map
551	     * @return the mapped owner DTO
552	     */
553	    private OwnerDto toOwnerDto(Owner owner) {
554	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
555	        return ownerMapper.toOwnerDto(owner);
556	    }
557	
558	    /**
559	     * Counts the members of the given owner's household - the owners that share this owner's
560	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
561	     * is {@code null}) is its own sole member, so the count is one.
562	     *
563	     * @param owner the owner whose household is being sized
564	     * @return the number of owners sharing this owner's household (one when it has no household)
565	     */
566	    private int countHouseholdMembers(Owner owner) {
567	        String householdId = owner.getHouseholdId();
568	        if (householdId == null) {
569	            return 1;
570	        }
571	        return (int) this.clinicService.findAllOwners().stream()
572	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
573	            .count();
574	    }
575	
576	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
577	        String lastName = normalizeHouseholdField(owner.getLastName());
578	        String address = normalizeAddress(owner.getAddress());
579	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
580	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
581	                && normalizeAddress(existing.getAddress()).equals(address))
582	            .toList();
583	        if (housemates.isEmpty()) {
584	            return;
585	        }
586	        if (!Boolean.TRUE.equals(sharesHousehold)) {
587	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
588	        }
589	        String householdId = generateHouseholdId(lastName, address);
590	        owner.setHouseholdId(householdId);
591	        for (Owner housemate : housemates) {
592	            if (!householdId.equals(housemate.getHouseholdId())) {
593	                housemate.setHouseholdId(householdId);
594	                this.clinicService.saveOwner(housemate);
595	            }
596	        }
597	    }
598	
599	    /**
600	     * Builds the stable identifier shared by the members of one household. It is derived purely from
601	     * the normalized last name and address, so every owner of a given household deterministically
602	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
603	     * two normalized fields joined by a single space.
604	     *
605	     * @param normalizedLastName the household's last name, already normalized for comparison
606	     * @param normalizedAddress the household's address, already normalized for comparison
607	     * @return the shared household identifier
608	     */
609	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
610	        String key = normalizedLastName + '�' + normalizedAddress;
611	        try {
612	            byte[] digest = MessageDigest.getInstance("SHA-256")
613	                .digest(key.getBytes(StandardCharsets.UTF_8));
614	            StringBuilder hex = new StringBuilder();
615	            for (byte b : digest) {
616	                hex.append(String.format("%02X", b));
617	                if (hex.length() >= 12) {
618	                    break;
619	                }
620	            }
621	            return hex.substring(0, 12);
622	        } catch (NoSuchAlgorithmException e) {
623	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
624	        }
625	    }
626	
627	    /**
628	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
629	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
630	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
631	     * expands common abbreviations.
632	     *
633	     * @param value the raw last name, or {@code null}
634	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
635	     */
636	    private String normalizeHouseholdField(String value) {
637	        if (value == null) {
638	            return "";
639	        }
640	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
641	    }
642	}
